import{_ as o,l,o as e,c as s,v as r,p as i,x as t,d as n,i as d,S as q}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"KL 散度与交叉熵","description":"","frontmatter":{"title":"KL 散度与交叉熵","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kl-cross-entropy.md","filePath":"cs/kl-cross-entropy.md","lastUpdated":1789023840000}'),h={name:"cs/kl-cross-entropy.md"};function c(_,a,D,m,u,x){const p=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="kl-散度与交叉熵" tabindex="-1">KL 散度与交叉熵 <a class="header-anchor" href="#kl-散度与交叉熵" aria-label="Permalink to &quot;KL 散度与交叉熵&quot;">​</a></h1><div class="epigraph"><p>$D(p\\|q)=\\sum p\\log\\frac{p}{q}$ 是用 $q$ 给真正来自 $p$ 的符号编码时，多付的平均比特；交叉熵 $H(p,q)=H(p)+D(p\\|q)$。</p><footer>—— 据 Kullback and Leibler, 1951；Cover and Thomas 整理</footer></div><p>上一课<a href="/cs/rate-distortion">率失真</a> 的目标里出现 \\(I(X;\\hat X)=D(p(x,\\hat x)\\|p(x)p(\\hat x))\\)。主干<a href="/cs/entropy-bits">熵</a> 有 \\(H\\)，互信息课有 \\(I\\)。缺口是把<strong>相对熵</strong>写成编码多付的比特，并接上交叉熵——后课最大熵、以及别处训练损失都用这个差，本栏只钉信息论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(D(p\\|q)\\ge 0\\)，等号当 \\(p=q\\)（Gibbs）。不对称：\\(D(p\\|q)\\ne D(q\\|p)\\)。不是度量。编码：若按 \\(q\\) 做理想码长 \\(-\\log q\\)，真实期望是 \\(-\\sum p\\log q=H(p,q)\\)，比 \\(H(p)\\) 多 \\(D(p\\|q)\\)。模型错了，压缩变差，下界仍是真熵。</p><p>链式：\\(D(p(x,y)\\|q(x,y))=D(p(x)\\|q(x))+D(p(y|x)\\|q(y|x))\\)。互信息 \\(I(X;Y)=D(p(x,y)\\|p(x)p(y))\\)。</p><h3 id="不是「距离」也不是准确率" tabindex="-1">不是「距离」也不是准确率 <a class="header-anchor" href="#不是「距离」也不是准确率" aria-label="Permalink to &quot;不是「距离」也不是准确率&quot;">​</a></h3><p>KL 可无穷（\\(q\\) 在 \\(p\\) 的支撑上为零）。交叉熵最小 \\(\\ne\\) 分类正确率最大，除非把 \\(q\\) 解释成 softmax 一类模型——那是用法，本课定义不依赖标签。</p><p><span class="marginnote">Kullback–Leibler 1951。Cover–Thomas 第 2 章。Sanov、大偏差把 \\(D\\) 当指数速率，点名。本课不把注意力或 token 损失写进主线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用二元 \\(p\\ne q\\) 算一个数，解释多付的比特。强调顺序：\\(p\\) 真、\\(q\\) 码本。对照 Hamming：几何距离不管 \\(p\\)；KL 不管几何，只管测度。</p>',11)),(e(),i(q,null,{default:t(()=>[d(p,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%9C%9F%20p%22%5D%20--%3E%20H%5B%22H(p)%20%E7%90%86%E6%83%B3%E7%A0%81%E9%95%BF%22%5D%0A%20%20Q%5B%22%E6%A8%A1%E5%9E%8B%20q%22%5D%20--%3E%20CE%5B%22%E4%BA%A4%E5%8F%89%E7%86%B5%20H(p%2Cq)%22%5D%0A%20%20H%20--%3E%20KL%5B%22%E5%B7%AE%20%3D%20D(p%7C%7Cq)%22%5D%0A%20%20CE%20--%3E%20KL%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了 \\(D\\)，最大熵「在约束下让 \\(p\\) 尽量无偏」可写成最小化相对均匀的 \\(D\\)，下一课。信道、率失真的优化都是在凸集上动 \\(D\\) 或 \\(I\\)。本课只把尺子交到手上。</p><p>数据处理：Markov 链上 \\(D\\) 不增，点名。</p><p>Pinsker：\\(\\|p-q\\|_1^2 \\le 2D(p\\|q)\\)，把 KL 换成全变差。数据处理：Markov \\(X\\to Y\\to Z\\) 则 \\(D(p_Z\\|q_Z)\\le D(p_Y\\|q_Y)\\)。交叉熵作为训练损失时，\\(p\\) 是经验分布、\\(q\\) 是模型——那是用法；本课定义不依赖样本。反向 KL 与正向 KL 的零强迫不同，变分推断点名。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 \\(f\\)-散度族全文，不证 Pinsker。不把反向 KL 与正向 KL 的变分推断写完。后课默认：\\(D(p\\|q)\\) 是额外码长；交叉熵 \\(=H+D\\)。下一课最大熵原理。</p><p>\\(p\\) 是真、\\(q\\) 是码本或模型，顺序不能翻。\\(D\\) 不是度量，可以无穷。互信息是到独立乘积的 KL，率失真与信道都在这把尺子上优化。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(D(p\\|q)\\) 非负、不对称；编码解释为多付比特。</li><li>交叉熵 \\(=H(p)+D(p\\|q)\\)。</li><li>\\(I\\) 是到乘积分布的 KL。</li><li>出处：Kullback and Leibler, 1951；Cover and Thomas。</li></ul>',9))])}const b=o(h,[["render",c]]);export{k as __pageData,b as default};
